def prune_moments(G,t,keep_counts,nmain):
 R=np.linalg.inv(G)
 c=R@t
 ids=np.arange(len(t))
 out={}
 for size in range(len(t),min(keep_counts)-1,-1):
  if size in keep_counts: out[size]=(ids.copy(),c.copy())
  if size==min(keep_counts): break
  scores=c*c/np.diag(R); scores[ids<nmain]=np.inf
  j=int(np.argmin(scores)); k=np.arange(size)!=j
  r=R[k,j].copy(); rr=R[j,j]
  c=c[k]-c[j]*r/rr
  R=R[k][:,k]-np.outer(r,r)/rr
  ids=ids[k]
 return out

